/**
 * TradeWarRoom (#792 / #1173 / #843 / #842; plain-English rework per owner
 * directive 2026-10-19, Part 1 + the frontend of Part 4; Lane 6).
 *
 * Payloads in `fixtures/trade-war-room/` are REAL `POST /api/trade/analyze`
 * output: generated by `tests/trade/war_room_ui_payloads.py` through
 * `simulate_trade` + `analyze_trade`, and `tests/trade/test_war_room_ui_fixtures.py`
 * fails if the backend stops emitting exactly these.  `fixtures/trade-war-room-mock/`
 * holds ONE route-mock shaped payload (A.J. Brown in / Justin Herbert out, the
 * owner's observed values) — every expectation on it is derived from its
 * fields, never hardcoded as production output.  The component computes
 * nothing: it words the packet.
 */
import { act, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import TradeWarRoom, { ANALYZE_TIMEOUT_MS, SLOW_NOTICE_MS } from "@/components/trade/TradeWarRoom";
