  it("nothing visible at a glance carries an internal identifier or an all-caps code", async () => {
    // Two oracles.  `hasInternalIdentifier` is the production predicate; the
    // explicit corpus below is INDEPENDENT of it, so a hole in the predicate
    // cannot also hide the leak here.  ROSTER_UNMEASURED's and ROSTER_ERROR's
    // backend texts carry reason codes ("not_computed", "error:KeyError"), so
    // this fails if any of them is ever shown raw.
    const ORACLE = [
      ["snake_case", /[A-Za-z0-9]_[A-Za-z0-9]/],
      ["camelCase", /(?:^|[\s(\[{"'‘“])[a-z]+[A-Z][A-Za-z]*/],
      // KTC and FAAB are display words the owner approved ("KTC adjustment
      // method", "$5 FAAB").
      ["ALL_CAPS", /\b(?!III\b|KTC\b|FAAB\b)[A-Z]{3,}\b|\b[A-Z]+_[A-Z_]+\b/],
      ["word:Word", /\b[a-z]+:[A-Za-z]/],
    ];
    const clean = (text, where) => {
      expect(hasInternalIdentifier(text), `${where}: ${text}`).toBe(false);
      for (const [name, re] of ORACLE) expect(text, `${where} (${name})`).not.toMatch(re);
    };
    const fixtures = [
      CONSOLIDATION,
      FORCED,
      PARTIAL,
      ASSET_ONLY,
      AJ_BROWN,
      PARTIAL_LONG_TERM,
      ROSTER_UNMEASURED,
      ROSTER_ERROR,
      STRATEGY_CUT_NO,
      SUPERFLEX,
      KTC_ROLLBACK,
      COMPARABLES,
      OUTGOING_NOT_HELD,
      OVER_LIMIT,
      TOO_CLOSE,
    ];
    for (const fixture of fixtures) {
      const view = await renderWith(fixture);
      const name = fixture._fixture?.scenario || "aj-brown";
      // The WHOLE War Room with every disclosure open (the engine's headline
      // words are the official answer).
      for (const section of [
        "Lineup impact, player by player",
        "Your lineup before and after",
        "Arguments, objections and uncertainty",
        "Sources, simulations and methodology",
      ]) {
        const button = screen.queryByRole("button", { name: section });
        if (button) fireEvent.click(button);
      }
      clean(
        readText(view.container).replace(fixture.analysis.decision.headlineText, ""),
        `${name} War Room`,
      );
      view.unmount();
      // ...and the Reasoning tab: what would change it, and the coverage
      // table's every cell (its Note column carried "error:KeyError").
      const tab = render(
        <TradeDecisionReasoning decision={fixture.analysis.decision} emptyText="x" />,
      );
      const changes = screen.queryByTestId("decision-what-would-change");
      if (changes) {
        // The engine's own headline words ("would be NO — TOO CLOSE") are the
        // decision's official answer, not a code; the rest must be plain.
        const headlines = /YES — MAKE THE TRADE|NO — DO NOT MAKE THE TRADE|NO — TOO CLOSE/g;
        clean(readText(changes).replace(headlines, ""), `${name} what would change`);
      }
      clean(
        readText(screen.getByRole("table", { name: /Evidence coverage/ })),
        `${name} coverage table`,
      );
      tab.unmount();
    }
  }, 60_000);

